update loyalties set exp_modifier = v.exp_modifier, breeding_modifier = v.breeding_modifier
from (values
  ('0', 0.5, -5),
  ('1', 0.7, -3),
  ('2', 1, 0),
  ('3', 1.2, 2),
  ('4', 1.5, 5),
  ('5', 1.8, 8)
) as v(name, exp_modifier, breeding_modifier)
where loyalties.name = v.name;

on conflict (level_number) do nothing;

