on conflict (name) do nothing;

on conflict (name) do nothing;

on conflict (name) do nothing;

on conflict (name) do nothing;

on conflict (name) do nothing;

on conflict (name) do nothing;

update afflictions set catch_modifier = v.modifier
from (values
  ('Burned', 10),
  ('Confused', 10),
  ('Infatuated', 10),
  ('Poisoned', 10),
  ('Frozen', 15),
  ('Paralyzed', 15),
  ('Asleep', 15)
) as v(name, modifier)
where lower(afflictions.name) = lower(v.name);

on conflict (name) do nothing;

on conflict (name) do nothing;

