insert into origins (name, lifestyle, description) values
  ('Academic', 'Difficult', 'Roll with advantage on Concentration, History, Investigate, Nature, Perception or Programming checks related to your field of study'),
  ('Entertainer', 'Comfortable', 'Roll with advantage on Bluff, Concentration, Diplomacy, History, Insight or Perform checks related to your profession'),
  ('Athlete', 'Comfortable', 'Roll with advantage on Acrobatics, Athletics, Concentration, Constitution or Sleight of hand checks related to your profession'),
  ('Backpacker', 'Difficult', 'Choose 2 favored terrains and roll with advantage on Athletics, Constitution, Nature, Perception, Pokémon handling or Stealth checks while in that terrain'),
  ('Doctor', 'Comfortable', 'Roll with advantage on Concentration, Diplomacy, Insight, Medicine or Sleight of hand checks related to your profession'),
  ('Grunt', 'Difficult', 'Roll with advantage on Bluff, Diplomacy, Insight, Programming, Sleight of hand or Stealth checks related to your criminal history. Additionally, you have a contact within the criminal organization that tells you what to do'),
  ('Gym trainer', 'Modest', 'Choose 2 personality traits of your gym leader. Roll with advantage on Concentration, Diplomacy, History, Insight, Perception or Pokémon handling checks to find out about a gym leader or their Pokémon that has one of the same personality traits'),
  ('Laborer', 'Modest', 'Roll with advantage on Athletics, Constitution, Engineering, Nature, Perception or Pokémon handling checks related to your profession'),
  ('Ranger', 'Modest', 'Roll with advantage on Concentration, Constitution, Diplomacy, Investigate, Nature or Stealth checks when you are Talented in them and are acting as a ranger'),
  ('Raring to go', 'Modest', 'Choose one stat and raise it by 1. When you get to level 3, 7, and 11, you may take one additional Skill Talent from your new class.'),
  ('Salaryperson', 'Comfortable', 'Roll with advantage on Concentration, Diplomacy, History, Insight, Perform or Programming checks related to your profession'),
  ('Service industry', 'Difficult', 'Roll with advantage on Bluff, Concentration, Constitution, Diplomacy, Insight, Investigate or Perform checks related to your profession'),
  ('Spiritualist', 'Difficult', 'Choose 2 beings or belief systems and roll with advantage on Concentration, Diplomacy, History, Insight, Medicine, Nature or Pokémon handling checks related to those. In addition, if you meditate or pray at least 1 minute before a check that is related to your chosen faith, you can also roll with advantage.'),
  ('Technician', 'Comfortable', 'Roll with advantage on Concentration, Engineering, Investigate, Programming or Sleight of hand checks related to your profession'),
  ('Trust funded', 'Wealthy', 'When purchasing goods under 3.000 credits in one day, you do not deplete your savings')
