  ('Thunder punch', 'Melee', (select id from types where lower(name) = lower('Electric')), 'physical', '3/day', '3d8', 'On hit, if you got 17 or higher on Accuracy Check, the target is Paralyzed'),
  ('Thunder shock', 'Ranged (20ft)', (select id from types where lower(name) = lower('Electric')), 'special', 'At will', '1d12', 'On hit, if you got 18 or higher on Accuracy Check, the target is Paralyzed'),
  ('Thunder wave', 'Ranged (20ft)', (select id from types where lower(name) = lower('Electric')), 'effect', '1/day', null, 'On hit, the target is Paralyzed'),
  ('Thunderbolt', 'Ranged (30ft)', (select id from types where lower(name) = lower('Electric')), 'special', '3/day', '3d10', 'On hit, if you got 18 or higher on Accuracy Check, the target is Paralyzed'),
  ('Tidepools', 'Field', (select id from types where lower(name) = lower('Water')), 'effect', '3/day', null, 'You create a circle of Tide Terrain with a 60ft diameter. Pokémon with the skill Flopper or Beached ignore those skills while acting within Tide Terrain. Tide Terrain does not replace other Terrains nor does it get replaced by other Terrains. This terrain disappears after 5 mins'),
  ('Tidy up', 'Ranged (30ft burst)', (select id from types where lower(name) = lower('Normal')), 'effect', '3/day', null, 'Any Hazards or Coats within range are destroyed. If you destroyed any Hazards or Coats, your Attack is +1 and your Speed is +1 for 10 mins'),
  ('Torch song', 'Ranged (30ft)', (select id from types where lower(name) = lower('Fire')), 'special', '3/day', '3d10', 'On hit, your Special Attack is +2 for 10 mins'),
  ('Toxic', 'Melee', (select id from types where lower(name) = lower('Poison')), 'effect', '1/day', null, 'Toxic has -3 during Accuracy Check, unless the user is Poison type. On hit, the target is Toxified'),
  ('Toxic spikes', 'Ranged (20ft burst)', (select id from types where lower(name) = lower('Poison')), 'effect', '3/day', null, 'Place the Toxic Spikes Hazard in the area surrounding you. Toxic Spikes Hazard has the following ability: When a foe moves through Toxic Spikes Hazard during their turn and are on the ground, they are Poisoned. If the Toxic Spikes Hazard has multiple layers, it will Toxify foes instead of Poisoning them instead. This Hazard disappears after 2 mins'),
  ('Toxic thread', 'Ranged (20ft)', (select id from types where lower(name) = lower('Poison')), 'effect', '1/day', null, 'On hit, the target is Poisoned and the target’s Speed is -1 until they are no longer Poisoned'),
  ('Trailblaze', 'Melee', (select id from types where lower(name) = lower('Grass')), 'physical', 'At will', '2d6', 'On hit, your Speed is +1 for 10 mins'),
  ('Transform', 'Ranged (25ft)', (select id from types where lower(name) = lower('Normal')), 'effect', 'At will', null, 'You transform into a copy of the target changing all of your stats except for HP. You copy its stats, skills, and passives. You can use any of the target’s moves. While transformed, you lose access to your regular moves, skills, passives, and biology. Except for stats, this information is not provided to you. Transform may not target Legendary Pokémon. Transform lasts for 2 hours or until Ditto chooses to change back as an action. Transform fails if used by anything but a Ditto'),
  ('Tri attack', 'Ranged (20ft)', (select id from types where lower(name) = lower('Normal')), 'special', '3/day', '3d10', 'On hit, if you got 17 or higher on Accuracy Check, the target is randomly either Paralyzed, Burned, or Frozen'),
  ('Trick', 'Melee', (select id from types where lower(name) = lower('Psychic')), 'effect', '1/day', null, 'On hit, you and the target trade any held items. If only you or the target has an item, take or give the item to exchange who has possession of it'),
  ('Trick-or-treat', 'Melee', (select id from types where lower(name) = lower('Ghost')), 'effect', '3/day', null, 'On hit, put a Treat Coat on the target. The Coat has the following ability: You lose your current Types and become only Ghost-type for 10 mins'),
  ('Trick room', 'Field', (select id from types where lower(name) = lower('Psychic')), 'effect', '3/day', null, 'You create a circle of Tricky Terrain with a 60ft diameter. Within the Tricky terrain, turn orders are reversed during each round. If some are outside of Tricky terrain while others are within Tricky terrain, all actions are still made in reverse order. This terrain disappears after 2 mins'),
  ('Triple arrows', 'Ranged (30ft)', (select id from types where lower(name) = lower('Fighting')), 'physical', '3/day', '1d12', 'Triple Arrows is a Scatter attack. Up to 3 attacks. Triple Arrow’s third attack on hit deals an additional 1d12 damage. On hit, any target’s Defense is -1 for 10 mins'),
  ('Triple axel', 'Melee', (select id from types where lower(name) = lower('Ice')), 'physical', '3/day', '1d12', 'Triple Axel is a Scatter attack. Up to 3 attacks. Triple Axel’s third attack on hit deals an additional 1d12 damage'),
  ('Triple dive', 'Melee', (select id from types where lower(name) = lower('Water')), 'physical', '3/day', '1d12', 'Triple Dive is a Scatter attack. Up to 3 attacks. Triple Dive’s third attack on hit deals an additional 1d12 damage'),
  ('Triple kick', 'Melee', (select id from types where lower(name) = lower('Fighting')), 'physical', '3/day', '1d12', 'Triple Kick is a Scatter attack. Up to 3 attacks. Triple Kick’s third attack on hit deals an additional 1d12 damage'),
  ('Trop kick', 'Melee', (select id from types where lower(name) = lower('Grass')), 'physical', '3/day', '3d8', 'On hit, the target’s Attack is -1 for 10 mins'),
  ('Twin beam', 'Ranged (30ft)', (select id from types where lower(name) = lower('Psychic')), 'special', '3/day', '2d8', 'Twin Beam is a Scatter attack. It has two attacks'),
  ('Twineedle', 'Melee', (select id from types where lower(name) = lower('Bug')), 'physical', '3/day', '2d8', 'Twineedle is a Scatter attack. It has two attacks. On either hit, if you got 14 or higher on Accuracy Check, the target is Poisoned'),
  ('Twister', 'Ranged (15ft)', (select id from types where lower(name) = lower('Dragon')), 'special', 'At will', '1d12', 'On hit, if you got 18 or higher on Accuracy Check, the target is Stunned'),
  ('Uproar', 'Ranged (20ft burst)', (select id from types where lower(name) = lower('Normal')), 'special', '1/day', '3d10', 'Uproar is a three-turn move. On each of its turns, you can move normally, then roll Uproar''s accuracy check and damage. Sleeping Pokémon within range of Uproar are awoken and Pokémon cannot go to Sleep within Uproar’s range'),
  ('Vacuum wave', 'Ranged (15ft)', (select id from types where lower(name) = lower('Fighting')), 'special', 'At will', '2d6', 'Vacuum Wave has Priority'),
  ('Venom drench', 'Ranged (10ft)', (select id from types where lower(name) = lower('Poison')), 'effect', '3/day', null, 'Venom Drench can only target a Poisoned or Toxified enemy. On hit, the target’s Attack, Special Attack, and Speed are -3 for 10 mins'),
  ('Venoshock', 'Ranged (10ft)', (select id from types where lower(name) = lower('Poison')), 'special', '3/day', '2d10', 'If the target is Poisoned or Toxified, Venoshock has 4d10 for damage instead'),
  ('Vise grip', 'Melee', (select id from types where lower(name) = lower('Normal')), 'physical', 'At will', '2d8', 'No additional effect'),
  ('Victory dance', 'Self', (select id from types where lower(name) = lower('Fighting')), 'effect', '1/day', null, 'Your Attack, Special Attack, Defense, and Special Defense are all +2 for 5 mins'),
  ('Vine whip', 'Ranged (20ft)', (select id from types where lower(name) = lower('Grass')), 'physical', 'At will', '2d8', 'No additional effect'),
  ('Vital throw', 'Melee', (select id from types where lower(name) = lower('Fighting')), 'physical', '3/day', '3d8', 'You can’t miss targets with less than 15 Defense if the target already acted this round. On hit, move the target away from you 15ft'),
  ('Volt tackle', 'Melee', (select id from types where lower(name) = lower('Electric')), 'physical', '1/day', '5d12', 'On hit, you lose HP equal to 1/3rd of the damage you deal and if you got 18 or higher on Accuracy Check, the target is Paralyzed'),
  ('Wake-up slap', 'Melee', (select id from types where lower(name) = lower('Fighting')), 'physical', '3/day', '3d8', 'If Wake-Up Slap is used against a Sleeping target, Wake-Up Slap deals 5d8 for damage instead, then cures the target of Sleep. If you choose not to roll damage while using Wake-Up Slap, you do not need to roll an Accuracy Check'),
  ('Water gun', 'Ranged (20ft)', (select id from types where lower(name) = lower('Water')), 'special', 'At will', '2d6', 'No additional effect'),
  ('Water pulse', 'Ranged (20ft burst)', (select id from types where lower(name) = lower('Water')), 'special', '3/day', '3d8', 'On hit, if you got 16 or higher on Accuracy Check, the target is Confused'),
  ('Water shuriken', 'Ranged (15ft)', (select id from types where lower(name) = lower('Water')), 'special', 'At will', '1d4', 'Water Shuriken has Priority and is a Scatter attack. Up to 5 attacks'),
  ('Water sport', 'Melee', (select id from types where lower(name) = lower('Water')), 'effect', 'At will', null, 'Put a Water Coat on the target or yourself. The Coat has the following ability: Reduce damage from Fire attacks that hit you by 10. This Coat lasts for 2 mins'),
  ('Water spout', 'Ranged (30ft burst)', (select id from types where lower(name) = lower('Water')), 'special', '1/day', '3d10', 'If you are at Max HP, Water Spout has 5d12 for damage instead'),
  ('Waterfall', 'Melee', (select id from types where lower(name) = lower('Water')), 'physical', '3/day', '3d10', 'On hit, if you got 16 or higher on Accuracy Check, the target is Stunned'),
  ('Wave crash', 'Melee', (select id from types where lower(name) = lower('Water')), 'physical', '1/day', '3d12', 'On hit, you lose HP equal to 1/4th of the damage you deal. Your Speed is +2 for 10 mins'),
  ('Weather ball', 'Ranged (25ft)', (select id from types where lower(name) = lower('Normal')), 'special', '3/day', '3d8', 'If within weather, Weather Ball has 5d8 for damage instead and its type changes to match the weather'),
  ('Whirlpool', 'Ranged (10ft)', (select id from types where lower(name) = lower('Water')), 'special', '3/day', '1d4', 'On hit, the target is bound in place for 1d4 rounds. For each round the target is bound, it takes 1d4 damage on its turns'),
  ('Whirlwind', 'Ranged (20ft)', (select id from types where lower(name) = lower('Normal')), 'effect', '3/day', null, 'On hit, moves the target 60ft away'),
  ('Wild charge', 'Melee', (select id from types where lower(name) = lower('Electric')), 'physical', '3/day', '3d10', 'On hit, you lose HP equal to 1/4th of the damage you deal'),
  ('Will-o-wisp', 'Ranged (10ft)', (select id from types where lower(name) = lower('Fire')), 'effect', '1/day', null, 'On hit, the target is Burned'),
  ('Wing attack', 'Melee', (select id from types where lower(name) = lower('Flying')), 'physical', 'At will', '2d8', 'No additional effect'),
  ('Wish', 'Melee', (select id from types where lower(name) = lower('Normal')), 'effect', '1/day', null, 'Target an ally or yourself. After the target acts during the next round, they are healed HP equal to half of the target ’s Max HP'),
  ('Wonder room', 'Field', (select id from types where lower(name) = lower('Psychic')), 'effect', '3/day', null, 'You create a circle of Wonderful Terrain with a 60ft diameter. Anyone who attacks within the Wonderful terrain makes Attack Accuracy Checks against Special Defense and Special Attack Accuracy Checks against Defense. This terrain disappears after 2 mins'),
  ('Wood hammer', 'Melee', (select id from types where lower(name) = lower('Grass')), 'physical', '1/day', '5d12', 'On hit, you lose HP equal to 1/3rd of the damage you deal'),
  ('Wrap', 'Melee', (select id from types where lower(name) = lower('Normal')), 'physical', 'At will', '1d4', 'On hit, the target is bound to you for 1d4 rounds. For each round the target is bound, it takes 1d4 damage on its turns'),
  ('X-scissor', 'Melee', (select id from types where lower(name) = lower('Bug')), 'physical', '3/day', '3d10', 'No additional effect'),
  ('Yawn', 'Melee', (select id from types where lower(name) = lower('Normal')), 'effect', '3/day', null, 'On hit, the target falls Asleep after its next turn'),
  ('Zap cannon', 'Ranged (30ft)', (select id from types where lower(name) = lower('Electric')), 'special', '1/day', '5d12', 'Zap Cannon has –5 during Accuracy Check. On hit the target is Paralyzed'),
  ('Zen headbutt', 'Melee', (select id from types where lower(name) = lower('Psychic')), 'physical', '3/day', '3d10', 'On hit, if you got 18 or higher on Accuracy Check, the target is Stunned'),
  ('Zing zap', 'Melee', (select id from types where lower(name) = lower('Electric')), 'physical', '3/day', '3d10', 'On hit, if you got 18 or higher on Accuracy Check, the target is Stunned'),
  ('Unbreakable armor', 'Self', (select id from types where lower(name) = lower('Normal')), 'effect', '3/day', null, 'Your Defense is +4 for 10 mins, your Attack and Special Attack is -10 for 10 mins'),
  ('Migraine', 'Self', (select id from types where lower(name) = lower('Normal')), 'effect', '3/day', null, 'You lose HP equal to half of your Max HP, then your Special Attack is +6 for 10 mins'),
  ('Unbreakable barrier', 'Self', (select id from types where lower(name) = lower('Normal')), 'effect', '3/day', null, 'Your Special Defense is +4 for 10 mins, your Attack and Special Attack is -10 for 10 mins'),
  ('Mach speeds', 'Self', (select id from types where lower(name) = lower('Normal')), 'effect', '3/day', null, 'Your Speed is +8 for 10 mins, your Defense and Special Defense is -3 for 10 mins'),
  ('Sync move', 'Ranged (30ft beam)', (select id from types where lower(name) = lower('Special/Variable')), 'either', '1/day', '3d12', 'You can’t miss targets with less than 15 Defense or Special Defense'),
  ('Type smasher', 'Melee', (select id from types where lower(name) = lower('Special/Variable')), 'physical', '3/day', '3d10', 'On hit, your Attack is +1 for 10 mins'),
  ('Type flash', 'Ranged (25ft)', (select id from types where lower(name) = lower('Special/Variable')), 'special', '3/day', '3d10', 'On hit, your Special Attack is +1 for 10 mins')
