insert into passives (name, description, passive_type, context) values
  ('Adaptibility', 'Moves that are the same type as you, +4 damage', 'ability', 'combat'),
  ('Aerilate', 'Your normal moves become flying moves', 'ability', 'combat'),
  ('Aftermath', 'When knocked out by a melee attack, deal 1d20 damage to the attacker', 'ability', 'combat'),
  ('Analytic', 'When attacking a foe that has already acted this round, +4 damage', 'ability', 'combat'),
  ('Anger shell', 'While you are below 20HP, +4 damage', 'ability', 'combat'),
  ('Armor tail', 'You are immune to priority attacks that are used out of turn order during combat', 'ability', 'combat'),
  ('Aroma veil', 'You and your allies within 10ft are immune to the effects of Heal block, Taunt, Encore, Disable and Cursed body', 'ability', 'combat'),
  ('Battle armor', 'Critical hits are treated as normal hits against you', 'ability', 'combat'),
  ('Big pecks', 'Your defense can''t be lowered by your foes', 'ability', 'combat'),
  ('Blaze', 'While you are below 20HP, fire attacks +4 damage', 'ability', 'combat'),
  ('Cheek pouch', 'When you consume a berry, heal 10HP', 'ability', 'combat'),
  ('Clear body', 'Your stats can''t be lowered by your foes', 'ability', 'combat'),
  ('Cloud nine', 'As a free action, use Defog (uses 1 charge)', 'ability', 'combat'),
  ('Color change', 'After you take damage, your type becomes the damage type for 5 minutes', 'ability', 'combat'),
  ('Comatose', 'You are Asleep but can still act (immune to other afflictions)', 'ability', 'combat'),
  ('Commander', 'When adjacent to an allied Dondozo, Tatsugiri can go into Dondozo’s mouth as a free action. While inside the allied Dondozo’s mouth, Tatsugiri cannot act and its Skills and Passives cannot be used, but the allied Dondozo has +2 to its Attack, Defense, Special Attack, Special Defense, and Speed. Additionally, Tatsugiri cannot be targeted or hit by any attacks, is unaffected by the effects of any moves, and allows the allied Dondozo to use any of Tatsugiri’s moves', 'ability', 'combat'),
  ('Compound eyes', 'While using ranged attack, +1 accuracy', 'ability', 'combat'),
  ('Corrosion', 'You can Poison and Toxify Steel-types and Poison-types', 'ability', 'combat'),
  ('Costar', 'At the start of combat, copy a stat passive from your nearest ally', 'ability', 'combat'),
  ('Cud chew', 'When you consume a berry, the effect activates again 1 round later', 'ability', 'combat'),
  ('Curious medicine', 'Your stats and your adjacent ally''s stats cant be lowered by a foe', 'ability', 'combat'),
  ('Cursed body', 'Disable the first melee attack that hits', 'ability', 'combat'),
  ('Cute charm', 'Whenever you are hit with a melee attack, roll 1d4 (on 4, Infatuate the attacker)', 'ability', 'combat'),
  ('Damp', 'Chloroblast, Explosion, Misty explosion, and Selfdestruct fail to do anything if used within 40ft of you', 'ability', 'combat'),
  ('Dazzling', 'You may not be targeted by priority moves that are used out of turn', 'ability', 'combat'),
  ('Defeatist', 'When your HP is below 50%, -2 all stats', 'ability', 'combat'),
  ('Disguise', 'The first attack is negated (each encounter)', 'ability', 'combat'),
  ('Drizzle', 'As a free action, use Rain dance (uses 1 charge)', 'ability', 'combat'),
  ('Drought', 'As a free action, use Sunny day (uses 1 charge)', 'ability', 'combat'),
  ('Dry skin', 'In Sunny weather, lose 4HP each round. In Rainy weather, heal 4HP each round. You are immune to Water-type moves', 'ability', 'combat'),
  ('Early bird', 'Roll with advantage to wake from Sleep', 'ability', 'combat'),
  ('Earth eater', 'When hit by a ground-type move, instead heal half the damage done', 'ability', 'combat'),
  ('Effect spore', 'Whenever you are hit with a melee attack, roll 1d4 (on 4, randomly Paralyze/Poison/Sleep the attacker)', 'ability', 'combat'),
  ('Electric surge', 'As a free action, use Electric terrain (uses 1 charge)', 'ability', 'combat'),
  ('Electromorphosis', 'When hit by an attack that deals damage, you may use Charge as a free action', 'ability', 'combat'),
  ('Emergency exit', 'You cannot fight when first damaged below half of Max HP. You will want to run away or return to a Pokéball for 2 rounds. During those two rounds, your speed is doubled', 'ability', 'combat'),
  ('Exposed', 'When you move or use an attack, you have -8 defense, special defense until your next turn. You also deal -8 damage with all attacks', 'ability', 'combat'),
  ('Filter', 'Supereffective moves against you deal 4 less damage (after weakness)', 'ability', 'combat'),
  ('Flame body', 'Whenever you are hit with a melee attack, roll 1d4 (on 4, Burn the attacker)', 'ability', 'combat'),
  ('Flash fire', 'Immune to Fire-type attacks. If you are hit by a Fire-type attack, +4 damage for 2 minutes', 'ability', 'combat'),
  ('Flower veil', 'You and your allied Grass-type''s stats cannot be lowered by effects (range 25ft)', 'ability', 'combat'),
  ('Fluffy', 'Whenever you are hit with a melee attack, take half damage. But Fire damage is instead doubled', 'ability', 'combat'),
  ('Forecast', 'Your appearance and type changes with the weather.
